package com.wyrmscraiggolemtracker;

import net.runelite.api.Experience;

final class GolemEstimate
{
	private GolemEstimate()
	{
	}

	static int nextLevel(int xp)
	{
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp(xp) + 1);
	}

	static int xpRemaining(int xp)
	{
		return xpRemaining(xp, nextLevel(xp));
	}

	static int targetLevel(int xp, boolean useGoal, int configuredLevel)
	{
		return useGoal ? Math.max(1, Math.min(Experience.MAX_REAL_LEVEL, configuredLevel)) : nextLevel(xp);
	}

	static int xpRemaining(int xp, int targetLevel)
	{
		return Math.max(0, Experience.getXpForLevel(targetLevel) - xp);
	}

	static int golemsRemaining(int xp, int xpPerGolem)
	{
		return golemsRemaining(xp, xpPerGolem, nextLevel(xp));
	}

	static int golemsRemaining(int xp, int xpPerGolem, int targetLevel)
	{
		int remaining = xpRemaining(xp, targetLevel);
		int rate = Math.max(1, xpPerGolem);
		return (int) ((remaining + (long) rate - 1) / rate);
	}
}

package com.wyrmscraiggolemtracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(WyrmscraigGolemTrackerConfig.GROUP)
public interface WyrmscraigGolemTrackerConfig extends Config
{
	String GROUP = "wyrmscraig-golem-tracker";

	@ConfigItem(
		keyName = "useGoal",
		name = "Use level goal",
		description = "Track the chosen target level instead of the next Crafting level",
		position = 1
	)
	default boolean useGoal()
	{
		return false;
	}

	@Range(min = 1, max = 99)
	@ConfigItem(
		keyName = "targetLevel",
		name = "Target Crafting level",
		description = "Desired Crafting level (1–99), used when Use level goal is enabled",
		position = 2
	)
	default int targetLevel()
	{
		return 99;
	}

	@Range(min = 1, max = 200000000)
	@ConfigItem(
		keyName = "xpPerGolem",
		name = "Crafting XP per golem",
		description = "Total Crafting XP for a full golem, including shaping and core creation. Set this for your fur and XP modifiers."
	)
	default int xpPerGolem()
	{
		return 2440;
	}
}

package com.wyrmscraiggolemtracker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

public class WyrmscraigGolemTrackerOverlay extends OverlayPanel
{
	private final WyrmscraigGolemTrackerPlugin plugin;
	private final WyrmscraigGolemTrackerConfig config;

	@Inject
	WyrmscraigGolemTrackerOverlay(WyrmscraigGolemTrackerPlugin plugin,
		WyrmscraigGolemTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(190, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int xp = plugin.getCraftingXp();
		if (xp < 0)
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder().text("Wyrmscraig Golems").build());
		boolean useGoal = config.useGoal();
		int targetLevel = GolemEstimate.targetLevel(xp, useGoal, config.targetLevel());
		int remaining = GolemEstimate.xpRemaining(xp, targetLevel);
		if (remaining == 0 && !useGoal)
		{
			addLine("Crafting", "Level 99 reached");
		}
		else
		{
			addLine(useGoal ? "Target Crafting level" : "Next Crafting level", Integer.toString(targetLevel));
			if (remaining == 0)
			{
				addLine("Goal", "Reached");
			}
			addLine("XP remaining", QuantityFormatter.formatNumber(remaining));
			addLine("Golems (estimate)", QuantityFormatter.formatNumber(
				GolemEstimate.golemsRemaining(xp, config.xpPerGolem(), targetLevel)));
			addLine("XP per golem", QuantityFormatter.formatNumber(Math.max(1, config.xpPerGolem())));
		}
		return super.render(graphics);
	}

	private void addLine(String left, String right)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).build());
	}
}

package com.wyrmscraiggolemtracker;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Wyrmscraig Golem Tracker",
	description = "Shows the estimated golems needed for your next Crafting level",
	tags = {"crafting", "golems", "wyrmscraig"}
)
public class WyrmscraigGolemTrackerPlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private WyrmscraigGolemTrackerOverlay overlay;

	private volatile int craftingXp = -1;
	private volatile boolean running;

	@Override
	protected void startUp()
	{
		running = true;
		overlayManager.add(overlay);
		// Enabling the plugin while logged in must also initialise the tracker.
		clientThread.invoke(() ->
		{
			if (running && client.getGameState() == GameState.LOGGED_IN)
			{
				craftingXp = client.getSkillExperience(Skill.CRAFTING);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(overlay);
		craftingXp = -1;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (running && event.getSkill() == Skill.CRAFTING
			&& client.getGameState() == GameState.LOGGED_IN)
		{
			craftingXp = event.getXp();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN && running)
		{
			craftingXp = client.getSkillExperience(Skill.CRAFTING);
		}
		else
		{
			// Hide during logout/loading so another account's XP is never displayed.
			craftingXp = -1;
		}
	}

	int getCraftingXp()
	{
		return craftingXp;
	}

	@Provides
	WyrmscraigGolemTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WyrmscraigGolemTrackerConfig.class);
	}
}

package com.wyrmscraiggolemtracker;

import net.runelite.api.Experience;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class GolemEstimateTest
{
	@Test
	public void goalToggleSelectsConfiguredOrNextLevel()
	{
		int xp = Experience.getXpForLevel(60);
		assertEquals(85, GolemEstimate.targetLevel(xp, true, 85));
		assertEquals(61, GolemEstimate.targetLevel(xp, false, 85));
		assertEquals(1, GolemEstimate.targetLevel(xp, true, 0));
		assertEquals(99, GolemEstimate.targetLevel(xp, true, 100));
	}

	@Test
	public void countsAcrossMultipleLevelsAndRoundsUp()
	{
		// Level 1 to level 10 requires 1,154 XP: twelve 100-XP cycles.
		assertEquals(1154, GolemEstimate.xpRemaining(0, 10));
		assertEquals(12, GolemEstimate.golemsRemaining(0, 100, 10));
		assertEquals(11, GolemEstimate.golemsRemaining(100, 100, 10));
	}

	@Test
	public void completedOrLowerGoalsNeedNoGolems()
	{
		int xp = Experience.getXpForLevel(80);
		assertEquals(0, GolemEstimate.golemsRemaining(xp, 2440, 80));
		assertEquals(0, GolemEstimate.golemsRemaining(xp, 2440, 70));
	}

	@Test
	public void roundsUpPartialGolems()
	{
		int target = Experience.getXpForLevel(61);
		assertEquals(1, GolemEstimate.golemsRemaining(target - 1, 2440));
		assertEquals(1, GolemEstimate.golemsRemaining(target - 2440, 2440));
		assertEquals(2, GolemEstimate.golemsRemaining(target - 2441, 2440));
	}

	@Test
	public void advancesTargetAtLevelBoundary()
	{
		int xp = Experience.getXpForLevel(61);
		assertEquals(62, GolemEstimate.nextLevel(xp));
		assertEquals(Experience.getXpForLevel(62) - xp, GolemEstimate.xpRemaining(xp));
	}

	@Test
	public void stopsAtRealLevel99()
	{
		assertEquals(0, GolemEstimate.golemsRemaining(Experience.getXpForLevel(99), 2440));
		assertEquals(0, GolemEstimate.golemsRemaining(Experience.MAX_SKILL_XP, 2440));
	}

	@Test
	public void protectsAgainstInvalidConfiguredRate()
	{
		assertEquals(83, GolemEstimate.golemsRemaining(0, 0));
		assertEquals(1, GolemEstimate.golemsRemaining(0, Integer.MAX_VALUE));
	}
}

